head.script:
scwin.onpageload = function() {
	dm_webhook_form.set("projectId", "default-project-id");
	dm_webhook_form.set("loadingVisible", "N");
	dm_webhook_form.set("httpMethod", "POST");
	dm_webhook_form.set("contentType", "application/json");
	dm_webhook_form.set("active", "Y");

	scwin.initializeOptions();
	scwin.loadWebhookList();
	scwin.initializeEventHandlers();
};

scwin.initializeEventHandlers = function() {
	$p.observe(dm_webhook_form, "searchKeyword", function(value) {
		scwin.filterWebhooks(value);
	});
};

scwin.initializeOptions = function() {
	// 상태 옵션 초기화
	dlt_status_options.removeAll();
	dlt_status_options.insertRow(0);
	dlt_status_options.setCellData(0, "statusName", "전체");
	dlt_status_options.setCellData(0, "statusValue", "");

	var statusList = [
		{name: "활성", value: "ACTIVE"},
		{name: "비활성", value: "INACTIVE"},
		{name: "오류", value: "ERROR"}
	];

	for (var i = 0; i < statusList.length; i++) {
		var rowIndex = dlt_status_options.insertRow();
		dlt_status_options.setCellData(rowIndex, "statusName", statusList[i].name);
		dlt_status_options.setCellData(rowIndex, "statusValue", statusList[i].value);
	}

	// HTTP 메소드 옵션 초기화
	dlt_method_options.removeAll();
	var methodList = [
		{name: "POST", value: "POST"},
		{name: "PUT", value: "PUT"},
		{name: "PATCH", value: "PATCH"},
		{name: "GET", value: "GET"},
		{name: "DELETE", value: "DELETE"}
	];

	for (var i = 0; i < methodList.length; i++) {
		var rowIndex = dlt_method_options.insertRow();
		dlt_method_options.setCellData(rowIndex, "methodName", methodList[i].name);
		dlt_method_options.setCellData(rowIndex, "methodValue", methodList[i].value);
	}

	// 이벤트 옵션 초기화
	dlt_event_options.removeAll();
	var eventList = [
		{name: "푸시", value: "push"},
		{name: "풀 리퀘스트", value: "pull_request"},
		{name: "이슈", value: "issues"},
		{name: "커밋 코멘트", value: "commit_comment"},
		{name: "브랜치 생성/삭제", value: "create"},
		{name: "릴리즈", value: "release"}
	];

	for (var i = 0; i < eventList.length; i++) {
		var rowIndex = dlt_event_options.insertRow();
		dlt_event_options.setCellData(rowIndex, "eventName", eventList[i].name);
		dlt_event_options.setCellData(rowIndex, "eventValue", eventList[i].value);
		dlt_event_options.setCellData(rowIndex, "selected", "N");
	}
};

scwin.loadWebhookList = function() {
	var projectId = dm_webhook_form.get("projectId");

	scwin.showLoading("웹훅 목록 로딩 중...");

	var options = {
		id: "loadWebhookList",
		action: "/api/webhook/list",
		method: "GET",
		requestData: {
			projectId: projectId,
			searchKeyword: dm_webhook_form.get("searchKeyword"),
			searchStatus: dm_webhook_form.get("searchStatus")
		},
		target: dlt_webhookList,
		success: function(e) {
			scwin.hideLoading();
			console.log("웹훅 목록 로드 완료:", e);
			if (dlt_webhookList.getTotalRow() > 0) {
				dlt_webhookList.setFocusedRow(0);
				scwin.onWebhookSelect();
			}
		},
		error: function(e) {
			scwin.hideLoading();
			console.error("웹훅 목록 로드 실패:", e);
			$p.alert("웹훅 목록을 불러올 수 없습니다.");
		}
	};
	$p.executeService(options);
};

scwin.onWebhookSelect = function() {
	var selectedRow = dlt_webhookList.getFocusedRow();
	if (selectedRow >= 0) {
		var webhookId = dlt_webhookList.getCellData(selectedRow, "id");
		var webhookName = dlt_webhookList.getCellData(selectedRow, "name");
		var webhookUrl = dlt_webhookList.getCellData(selectedRow, "url");
		var method = dlt_webhookList.getCellData(selectedRow, "method");
		var status = dlt_webhookList.getCellData(selectedRow, "status");
		var events = dlt_webhookList.getCellData(selectedRow, "events");
		var active = dlt_webhookList.getCellData(selectedRow, "active");

		dm_webhook_form.set("selectedWebhookId", webhookId);
		dm_current_webhook.set("id", webhookId);
		dm_current_webhook.set("name", webhookName);
		dm_current_webhook.set("url", webhookUrl);
		dm_current_webhook.set("method", method);
		dm_current_webhook.set("status", status);
		dm_current_webhook.set("events", events);
		dm_current_webhook.set("active", active);
		dm_current_webhook.set("description", "GitHub 이벤트를 수신하는 웹훅");

		scwin.loadWebhookLog(webhookId);
	}
};

scwin.loadWebhookLog = function(webhookId) {
	if (!webhookId) return;

	var options = {
		id: "loadWebhookLog",
		action: "/api/webhook/log",
		method: "GET",
		requestData: {
			webhookId: webhookId,
			limit: 50
		},
		target: dlt_webhookLog,
		success: function(e) {
			console.log("웹훅 로그 로드 완료:", e);
		},
		error: function(e) {
			console.error("웹훅 로그 로드 실패:", e);
		}
	};
	$p.executeService(options);
};

scwin.createWebhook_onclick = function() {
	var webhookName = dm_webhook_form.get("webhookName");
	var webhookUrl = dm_webhook_form.get("webhookUrl");
	var httpMethod = dm_webhook_form.get("httpMethod");
	var contentType = dm_webhook_form.get("contentType");
	var headers = dm_webhook_form.get("headers");
	var events = dm_webhook_form.get("events");
	var active = dm_webhook_form.get("active");
	var projectId = dm_webhook_form.get("projectId");

	if (!webhookName) {
		$p.alert("웹훅명을 입력해주세요.");
		return;
	}

	if (!webhookUrl) {
		$p.alert("웹훅 URL을 입력해주세요.");
		return;
	}

	// URL 형식 검증
	var urlPattern = /^https?:\/\/.+/;
	if (!urlPattern.test(webhookUrl)) {
		$p.alert("올바른 URL 형식을 입력해주세요. (http:// 또는 https://로 시작)");
		return;
	}

	scwin.showLoading("웹훅 생성 중...");

	var options = {
		id: "createWebhook",
		action: "/api/webhook/create",
		method: "POST",
		requestData: {
			projectId: projectId,
			name: webhookName,
			url: webhookUrl,
			method: httpMethod,
			contentType: contentType,
			headers: headers,
			events: events,
			active: active
		},
		success: function(e) {
			scwin.hideLoading();
			console.log("웹훅 생성 완료:", e);

			var result = e.responseJSON || e;
			if (result.success) {
				$p.alert("웹훅이 성공적으로 생성되었습니다!");
				scwin.clearForm();
				scwin.loadWebhookList();
			} else {
				$p.alert("웹훅 생성에 실패했습니다: " + (result.message || "알 수 없는 오류"));
			}
		},
		error: function(e) {
			scwin.hideLoading();
			console.error("웹훅 생성 실패:", e);
			$p.alert("웹훅 생성에 실패했습니다.");
		}
	};
	$p.executeService(options);
};

scwin.updateWebhook_onclick = function() {
	var webhookId = dm_webhook_form.get("selectedWebhookId");
	if (!webhookId) {
		$p.alert("수정할 웹훅을 선택해주세요.");
		return;
	}

	var webhookName = dm_webhook_form.get("webhookName");
	var webhookUrl = dm_webhook_form.get("webhookUrl");
	var httpMethod = dm_webhook_form.get("httpMethod");
	var contentType = dm_webhook_form.get("contentType");
	var headers = dm_webhook_form.get("headers");
	var events = dm_webhook_form.get("events");
	var active = dm_webhook_form.get("active");

	if (!webhookName || !webhookUrl) {
		$p.alert("웹훅명과 URL을 입력해주세요.");
		return;
	}

	scwin.showLoading("웹훅 수정 중...");

	var options = {
		id: "updateWebhook",
		action: "/api/webhook/update",
		method: "PUT",
		requestData: {
			webhookId: webhookId,
			name: webhookName,
			url: webhookUrl,
			method: httpMethod,
			contentType: contentType,
			headers: headers,
			events: events,
			active: active
		},
		success: function(e) {
			scwin.hideLoading();
			console.log("웹훅 수정 완료:", e);

			var result = e.responseJSON || e;
			if (result.success) {
				$p.alert("웹훅이 성공적으로 수정되었습니다!");
				scwin.loadWebhookList();
			} else {
				$p.alert("웹훅 수정에 실패했습니다: " + (result.message || "알 수 없는 오류"));
			}
		},
		error: function(e) {
			scwin.hideLoading();
			console.error("웹훅 수정 실패:", e);
			$p.alert("웹훅 수정에 실패했습니다.");
		}
	};
	$p.executeService(options);
};

scwin.deleteWebhook_onclick = function() {
	var webhookId = dm_webhook_form.get("selectedWebhookId");
	if (!webhookId) {
		$p.alert("삭제할 웹훅을 선택해주세요.");
		return;
	}

	var webhookName = dm_current_webhook.get("name");
	if (!$p.confirm("웹훅 '" + webhookName + "'를 삭제하시겠습니까?\n이 작업은 되돌릴 수 없습니다.")) {
		return;
	}

	scwin.showLoading("웹훅 삭제 중...");

	var options = {
		id: "deleteWebhook",
		action: "/api/webhook/delete",
		method: "DELETE",
		requestData: {
			webhookId: webhookId
		},
		success: function(e) {
			scwin.hideLoading();
			console.log("웹훅 삭제 완료:", e);

			var result = e.responseJSON || e;
			if (result.success) {
				$p.alert("웹훅이 성공적으로 삭제되었습니다!");
				scwin.clearForm();
				scwin.loadWebhookList();
			} else {
				$p.alert("웹훅 삭제에 실패했습니다: " + (result.message || "알 수 없는 오류"));
			}
		},
		error: function(e) {
			scwin.hideLoading();
			console.error("웹훅 삭제 실패:", e);
			$p.alert("웹훅 삭제에 실패했습니다.");
		}
	};
	$p.executeService(options);
};

scwin.testWebhook_onclick = function() {
	var webhookId = dm_webhook_form.get("selectedWebhookId");
	var testPayload = dm_webhook_form.get("testPayload");

	if (!webhookId) {
		$p.alert("테스트할 웹훅을 선택해주세요.");
		return;
	}

	if (!testPayload) {
		testPayload = JSON.stringify({
			"test": true,
			"message": "웹훅 테스트 메시지",
			"timestamp": new Date().toISOString()
		}, null, 2);
		dm_webhook_form.set("testPayload", testPayload);
	}

	scwin.showLoading("웹훅 테스트 중...");

	var options = {
		id: "testWebhook",
		action: "/api/webhook/test",
		method: "POST",
		requestData: {
			webhookId: webhookId,
			testPayload: testPayload
		},
		success: function(e) {
			scwin.hideLoading();
			console.log("웹훅 테스트 완료:", e);

			var result = e.responseJSON || e;
			if (result.success) {
				$p.alert("웹훅 테스트가 성공했습니다!\n\n" +
					"응답 코드: " + result.statusCode + "\n" +
					"응답 시간: " + result.duration + "ms");
				scwin.loadWebhookLog(webhookId);
			} else {
				$p.alert("웹훅 테스트에 실패했습니다: " + (result.message || "알 수 없는 오류"));
			}
		},
		error: function(e) {
			scwin.hideLoading();
			console.error("웹훅 테스트 실패:", e);
			$p.alert("웹훅 테스트에 실패했습니다.");
		}
	};
	$p.executeService(options);
};

scwin.filterWebhooks = function(keyword) {
	if (!keyword) {
		for (var i = 0; i < dlt_webhookList.getTotalRow(); i++) {
			dlt_webhookList.setRowVisible(i, true);
		}
		return;
	}

	keyword = keyword.toLowerCase();
	for (var i = 0; i < dlt_webhookList.getTotalRow(); i++) {
		var webhookName = dlt_webhookList.getCellData(i, "name").toLowerCase();
		var webhookUrl = dlt_webhookList.getCellData(i, "url").toLowerCase();
		var visible = webhookName.indexOf(keyword) >= 0 || webhookUrl.indexOf(keyword) >= 0;
		dlt_webhookList.setRowVisible(i, visible);
	}
};

scwin.clearForm = function() {
	dm_webhook_form.set("selectedWebhookId", "");
	dm_webhook_form.set("webhookName", "");
	dm_webhook_form.set("webhookUrl", "");
	dm_webhook_form.set("httpMethod", "POST");
	dm_webhook_form.set("contentType", "application/json");
	dm_webhook_form.set("headers", "");
	dm_webhook_form.set("events", "");
	dm_webhook_form.set("active", "Y");
	dm_webhook_form.set("testPayload", "");

	dm_current_webhook.removeAll();
	dlt_webhookLog.removeAll();
};

scwin.loadWebhookToForm = function() {
	var selectedRow = dlt_webhookList.getFocusedRow();
	if (selectedRow >= 0) {
		dm_webhook_form.set("selectedWebhookId", dlt_webhookList.getCellData(selectedRow, "id"));
		dm_webhook_form.set("webhookName", dlt_webhookList.getCellData(selectedRow, "name"));
		dm_webhook_form.set("webhookUrl", dlt_webhookList.getCellData(selectedRow, "url"));
		dm_webhook_form.set("httpMethod", dlt_webhookList.getCellData(selectedRow, "method"));
		dm_webhook_form.set("events", dlt_webhookList.getCellData(selectedRow, "events"));
		dm_webhook_form.set("active", dlt_webhookList.getCellData(selectedRow, "active"));
	}
};

scwin.showLoading = function(message) {
	dm_webhook_form.set("loadingVisible", "Y");
	dm_webhook_form.set("loadingMessage", message || "처리 중...");
};

scwin.hideLoading = function() {
	dm_webhook_form.set("loadingVisible", "N");
};

scwin.grd_webhookList_onrowpositionchange = function(row) {
	scwin.onWebhookSelect();
};

scwin.grd_webhookList_oncelldblclick = function(row, col, colId) {
	scwin.loadWebhookToForm();
};

scwin.closeWindow_onclick = function() {
	if ($p.closePopup) {
		$p.closePopup();
	} else if (window.close) {
		window.close();
	}
};

scwin.refreshWebhookList_onclick = function() {
	scwin.loadWebhookList();
};
